function mintToken(address target, uint256 mintedAmount) onlyOwner {
    balanceOf[target] += mintedAmount;
    totalSupply += mintedAmount;
    Transfer(0, this, mintedAmount);
    Transfer(this, target, mintedAmount);
}

function burn(uint256 _value) returns (bool success) {
    require (balanceOf[msg.sender] > _value);             //internal check
    balanceOf[msg.sender] -= _value;                       //internal operation
    totalSupply -= _value;                                 //internal operation
    Burn(msg.sender, _value);                              //event
    return true;
}

function approve(address _spender, uint256 _value) returns (bool success) {
    allowance[msg.sender][_spender] = _value;
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) returns (bool success) {
    require (_value < allowance[_from][msg.sender]);      //check allowance
    allowance[_from][msg.sender] -= _value;               //decrease allowance
    _transfer(_from, _to, _value);                        //transfer tokens
    return true;
}
